export default async (ctx, client) => {
  let cursor, all = [], pages = 0;
  while (pages < 6) {
    const r = await client.notifications.list(cursor ? { cursor } : {});
    all = all.concat(r.notifications);
    if (!r.nextCursor) break;
    cursor = r.nextCursor;
    pages++;
