  const OLD = "lower(coalesce(metadata->>'author_handle','')) = 'buremba'";
  const NEW = "lower(coalesce(metadata->>'author_handle','')) = 'bu7emba'";

  const rows = await client.query(
    `SELECT sources, prompt, name, description FROM behaviors b
     JOIN behavior_versions v ON v.id = b.current_version_id
     WHERE b.id = 70`,
  );
  const row = rows[0];
  const sources = row.sources;
  const authored = sources.find((s) => s.name === 'authored_recent');
  if (!authored || !authored.query.includes(OLD)) {
    return { aborted: 'old pattern not present', found: authored?.query?.slice(0, 200) };
  }
  const patched = sources.map((s) =>
    s.name === 'authored_recent' ? { ...s, query: s.query.replace(OLD, NEW) } : s,
  );
  return {
    preview: patched.find((s) => s.name === 'authored_recent').query,
    otherSources: patched.filter((s) => s.name !== 'authored_recent').map((s) => s.name),
  };
}

