export default async (ctx, client) => {
  const list = await client.authProfiles.list().catch((e) => String(e));
  const profiles = Array.isArray(list?.profiles) ? list.profiles : Array.isArray(list) ? list : null;
  if (!profiles) return { raw: list };
  return profiles
    .filter((p) => [91, 21].includes(Number(p.id)) || String(p.provider ?? '').includes('google'))
    .map((p) => ({
      id: p.id, name: p.name, provider: p.provider, kind: p.kind ?? p.auth_type,
      scopes: p.scopes ?? p.config?.scopes ?? p.metadata?.scopes ?? null,
      status: p.status, expires_at: p.expires_at,
    }));
}

export default async (ctx, client) => {
  const test = await client.connections.test({ connection_id: 418 }).catch((e) => String(e));
  const reauth = await client.connections.reauthenticate({ connection_id: 418 }).catch((e) => String(e));
  return { test, reauth };
}

export default async (ctx, client) => {
  const rows = await client.query(`
    SELECT ap.id, ap.slug, ap.connector_key, ap.granted_scopes, ap.updated_at,
           c.id AS conn_id, c.app_auth_profile_id
    FROM auth_profiles ap
    JOIN connections c ON c.auth_profile_id = ap.id
    WHERE c.id = 418
  `);
  return rows;
};

export default async (ctx, client) => {
  const test = await client.connections.test({ connection_id: 418 });
  const trig = await client.feeds.trigger({ feed_id: 442 });
  return { test, trig };
};

export default async (ctx, client) => {
  for (let i = 0; i < 10; i++) {
    const f = await client.feeds.get({ feed_id: 442 });
    if (f.last_sync_status && f.last_sync_status !== "running") {
      return { status: f.last_sync_status, error: f.last_sync_error, items: f.last_items_collected, last_sync_at: f.last_sync_at };
    }
    await ctx.sleep(6000);
  }
  return { note: "still running" };
};

export default async (ctx, client) => {
  const r = await client.feeds.update({ feed_id: 442, schedule: "52 */2 * * *" });
  const after = await client.query(`SELECT id, schedule, next_run_at FROM feeds WHERE id = 442`);
  return { r, after };
};

