export default async (ctx, client) => {
  const b = await client.behaviors.get({ behavior_id: 5 });
  const srcs = (b.sources ?? b.version?.sources ?? []).map((s) => ({
    key: s.key ?? s.name,
    query: typeof s.query === "string" ? s.query.slice(0, 700) : s.query,
  }));
  return { name: b.name, schedule: b.schedule ?? b.cron, srcs };
};

export default async (ctx, client) => {
  const b = await client.behaviors.get({ behavior_id: 5 });
  return { keys: Object.keys(b), name: b.name, versionKeys: b.version ? Object.keys(b.version) : null };
};

export default async (ctx, client) => {
  const rows = await client.query(`
    SELECT bv.id, bv.version, bv.config::text AS cfg
    FROM behavior_versions bv
    JOIN behaviors b ON b.current_version_id = bv.id
    WHERE b.id = 5
  `);
  const cfg = JSON.parse(rows[0].cfg);
  return {
    version_id: rows[0].id,
    version: rows[0].version,
    sources: (cfg.sources ?? []).map((s) => ({ key: s.key, query: String(s.query ?? "").slice(0, 800) })),
  };
};

